// bindMirrors is called by Bind, before the first Step: the register mirror of each block is registered as a judge (on the sim, for every case) and the
// sampler of the slave ports declared. The sampler reads a port only while a judge wants bus.access of its instance.
func (u *PpuBench) bindMirrors() {
	look := func(inst, name string) *tb.Net {
		n, err := u.Net(inst, name)
		if err != nil {
			return nil
		}
		return n
	}
	u.mirrors = reg.NewChipMirrors(u.Sim, chipMirrorBlocks, look)
	fw.NewBusSampler(u.Sim, fw.Slaves(chipBusPorts, look))
}

// Mirror is the register mirror of the block instance called instance: Disable it, or Expect a value of a field it cannot know. A name that is not a
// block with registers ends the case.
func (u *PpuBench) Mirror(instance string) *reg.ChipMirror { return u.mirrors.Of(instance) }

// MirrorsOff turns every register mirror off for the case: nothing is sampled at the slave ports.
func (u *PpuBench) MirrorsOff() { u.mirrors.Disable() }
